for n,a,b,c,value,st in [(39,4*x-9,x*x-4*x+7,4,7,('x≥0에서 4x−9≤f(x)≤x²−4x+7이다. x→4의 f 극한을 구하라.','For x≥0, 4x−9≤f(x)≤x²−4x+7. Find the limit of f as x→4.')),(40,2*x,x**4-x*x+2,1,2,('모든 x에서 2x≤g(x)≤x⁴−x²+2이다. x→1의 g 극한을 구하라.','For all x, 2x≤g(x)≤x⁴−x²+2. Find the limit of g as x→1.'))]:
 add(n,st,[(d(r'\lim_{x\to'+str(c)+'}('+tex(a)+')='+str(value)+r'=\lim_{x\to'+str(c)+'}('+tex(b)+')'),d(r'\lim_{x\to'+str(c)+'}('+tex(a)+')='+str(value)+r'=\lim_{x\to'+str(c)+'}('+tex(b)+')')),('다항식의 연속성과 조임정리를 적용한다.','Apply polynomial continuity and the Squeeze Theorem.')],d(str(value)),('위·아래 식의 차는 '+m(tex(s.factor(b-a)))+'으로, 접근점에서 0이며 근방에서 음이 아니다.','The upper-minus-lower difference is '+m(tex(s.factor(b-a)))+', which vanishes at the approach point and is nonnegative nearby.'))
absitems=[(43,s.Abs(x+4)-2*x,-4,'+-',8,'절댓값도 연속이므로 |0|−2(−4)=8이다.','Absolute value is continuous, so |0|−2(−4)=8.'),(44,s.Abs(x+4)/(2*x+8),-4,'+-',None,'x<−4에서는 −1/2, x>−4에서는 1/2이다.','The expression equals −1/2 for x<−4 and 1/2 for x>−4.'),(45,(2*x-1)/s.Abs(2*x**3-x*x),s.Rational(1,2),'-',-4,'x<1/2이고 0 근처를 제외하면 분모=x²(1−2x)이므로 식은 −1/x²이다.','For x<1/2 near the approach point, the denominator is x²(1−2x), so the expression is −1/x².'),(46,(2-s.Abs(x))/(2+x),-2,'+-',1,'−2의 충분히 작은 근방에서 x<0, |x|=−x이므로 식은 (2+x)/(2+x)=1이다.','In a sufficiently small neighborhood of −2, x<0 and |x|=−x, making the quotient (2+x)/(2+x)=1.'),(47,1/x-1/s.Abs(x),0,'-',-s.oo,'x<0이면 |x|=−x이므로 식은 2/x이고 −∞로 발산한다.','For x<0, |x|=−x, so the expression is 2/x and diverges to −∞.'),(48,1/x-1/s.Abs(x),0,'+',0,'x>0이면 |x|=x이므로 식은 정확히 0이다.','For x>0, |x|=x, so the expression is identically zero.')]
for n,f,a,side,value,ko,en in absitems:
 form=d(r'\lim_{x\to'+tex(a)+('^'+side if side!='+-'else'')+'}'+tex(f))
 add(n,('절댓값의 부호를 나누어 '+form+'을 구하라.','Resolve the absolute-value signs to evaluate '+form),[(ko,en),('한쪽 극한을 구할 때에는 그쪽에서만 유효한 부호를 사용한다. 양쪽 극한은 두 값이 같아야 한다.','Use the sign valid on the specified side. A two-sided limit requires agreement between both sides.')],d(tex(value))if value is not None else('좌우가 달라 극한이 없다.','The one-sided limits disagree, so the limit does not exist.'),('각 한쪽 근방에서 절댓값을 제거한 식을 원식과 대조했다.','Compared the sign-resolved expression with the original on each relevant one-sided neighborhood.'))
sgndef=r'\operatorname{sgn}x=\begin{cases}-1&x<0\\0&x=0\\1&x>0\end{cases}'
add(49,('부호함수 '+d(sgndef)+'에 대해 (a)그래프를 그리고 (b)(i)0⁺, (ii)0⁻, (iii)0에서의 극한, (iv)0에서 |sgn x|의 극한을 구하라.','For the sign function '+d(sgndef)+', (a)sketch its graph and (b)find the limits at (i)0⁺, (ii)0⁻, (iii)0, and (iv)the limit of |sgn x| at 0.'),[('양의 입력에서 1, 음의 입력에서 −1이므로 좌우가 다르다. 절댓값을 취하면 x≠0에서 항상 1이다.','The value is 1 for positive inputs and −1 for negative inputs, so the sides disagree. Taking absolute values gives 1 for every x≠0.')],('(b)(i)1, (ii)−1, (iii)없음, (iv)1.','(b)(i)1, (ii)−1, (iii)does not exist, (iv)1.'),('sgn 0=0은 열린 근방의 두 상수값이나 절댓값 극한을 바꾸지 않는다.','The assignment sgn 0=0 does not change either punctured-neighborhood value or the absolute-value limit.'),['a','b(i)','b(ii)','b(iii)','b(iv)'])
D.fig(49,[panel('Sign function',(-3,3,-1.5,1.5),[[(-3,-1),(0,-1)],[(0,1),(3,1)]],[(0,-1,'open'),(0,0),(0,1,'open')],yticks=[-1,0,1])])
add(50,('g(x)=sgn(sin x)이다. (a)0⁺,0⁻,0,π⁺,π⁻,π의 순서로 극한을 구하고, (b)양쪽 극한이 없는 모든 a를 찾으며 (c)그래프를 그려라.','Let g(x)=sgn(sin x). (a)Find the limits at 0⁺,0⁻,0,π⁺,π⁻,π in that order. (b)Find every a where the two-sided limit fails. (c)Sketch the graph.'),[('sin x는 (kπ,(k+1)π)에서 부호 (−1)ᵏ을 가지며 kπ에서는 0이다.','On (kπ,(k+1)π), sin x has sign (−1)ᵏ; at kπ its sign value is zero.'),('모든 정수배 kπ에서 부호가 바뀌고, 그 사이에서는 상수이다.','The sign changes at every integer multiple kπ and is constant between these points.')],('(a)1,−1,없음,−1,1,없음. (b)a=kπ(k∈ℤ).','(a)1,−1,does not exist,−1,1,does not exist. (b)a=kπ for k∈ℤ.'),('π의 오른쪽은 sin x<0, 왼쪽은 sin x>0임을 확인하여 0 근방과 부호 순서가 반대임을 검산했다.','Immediately right of π the sine is negative and immediately left it is positive, confirming the reversal from the signs around zero.'),['a(i)','a(ii)','a(iii)','a(iv)','a(v)','a(vi)','b','c'])
cs=[];dots=[]
for k in range(-2,2):
 y=(-1)**k;cs.append([(k*math.pi,y),((k+1)*math.pi,y)]);dots.extend([(k*math.pi,y,'open'),((k+1)*math.pi,y,'open')])
dots += [(k*math.pi,0)for k in range(-2,3)]
D.fig(50,[panel('Sign of sine; repeats every 2 pi',(-2*math.pi,2*math.pi,-1.5,1.5),cs,dots,xticks=[k*math.pi for k in range(-2,3)],yticks=[-1,0,1])])
add(51,('g(x)=(x²+x−6)/|x−2|이다. (a)2⁺와 2⁻의 극한, (b)2의 양쪽 극한을 구하고 (c)그래프를 그려라.','For g(x)=(x²+x−6)/|x−2|, (a)find the limits at 2⁺ and 2⁻, (b)decide the two-sided limit at 2, and (c)sketch the graph.'),[(d(r'g(x)=(x+3)\frac{x-2}{|x-2|}=\begin{cases}-x-3&x<2\\x+3&x>2\end{cases}'),d(r'g(x)=(x+3)\frac{x-2}{|x-2|}=\begin{cases}-x-3&x<2\\x+3&x>2\end{cases}')),('오른쪽은 5, 왼쪽은 −5로 접근한다.','The right side approaches 5 and the left side approaches −5.')],('(a)(i)5, (ii)−5. (b)존재하지 않는다.','(a)(i)5, (ii)−5. (b)Does not exist.'),('분자 인수 (x−2)를 절댓값 분모와 약분할 때 남는 부호를 보존했다. x=2에서는 정의되지 않는다.','Preserved the sign left after dividing the numerator factor (x−2) by the absolute-value denominator. The function is undefined at 2.'),['a(i)','a(ii)','b','c'])
D.fig(51,[panel('Opposite linear branches',(-3,5,-8,9),[[(-3,0),(2,-5)],[(2,5),(5,8)]],[(2,-5,'open'),(2,5,'open')])])
add(52,('f(x)=x²+1(x<1), (x−2)²(x≥1)이다. (a)1의 좌우 극한, (b)양쪽 극한 존재 여부, (c)그래프를 구하라.','Let f(x)=x²+1 for x<1 and (x−2)² for x≥1. Find (a)the one-sided limits at 1, (b)whether the two-sided limit exists, and (c)the graph.'),[('왼쪽 식에 1을 대입하면 2, 오른쪽 식에 대입하면 1이다. 실제 f(1)=1은 오른쪽 조각에 속한다.','Substitution in the left formula gives 2 and in the right formula gives 1. The assigned value f(1)=1 belongs to the right piece.')],('(a)왼쪽 2, 오른쪽 1. (b)없음.','(a)Left 2, right 1. (b)Does not exist.'),('그래프에서 (1,2)는 열린 점, (1,1)은 닫힌 점으로 표시하여 조건 x<1과 x≥1을 보존했다.','The graph uses an open point at (1,2) and a filled point at (1,1), preserving the inequalities x<1 and x≥1.'),list('abc'))
D.fig(52,[panel('Two quadratic pieces',(-2,4,-.5,6),[samples(lambda z:z*z+1,-2,1),samples(lambda z:(z-2)**2,1,4)],[(1,2,'open'),(1,1)])])
add(53,('B(t)=4−t/2(t<2), √(t+c)(t≥2)이다. t→2에서 극한이 존재하게 하는 c를 구하라.','Let B(t)=4−t/2 for t<2 and √(t+c) for t≥2. Find c so that the limit as t→2 exists.'),[('왼쪽 극한은 4−1=3이다. 오른쪽 극한 √(2+c)가 3이어야 한다.','The left limit is 4−1=3. The right limit √(2+c) must equal 3.'),(d(r'\sqrt{2+c}=3\iff 2+c=9\iff c=7'),d(r'\sqrt{2+c}=3\iff 2+c=9\iff c=7'))],d(r'c=7,\quad L=3'),('c=7이면 2 근방에서 근호 내부가 양수이고 두 한쪽 극한이 정확히 3이다.','For c=7 the radicand is positive near 2 and both one-sided limits equal 3.'))
add(54,('g(x)=x(x<1), g(1)=3, g(x)=2−x²(1<x≤2), g(x)=x−3(x>2)이다. (a)(i)lim₁₋g,(ii)lim₁g,(iii)g(1),(iv)lim₂₋g,(v)lim₂₊g,(vi)lim₂g를 구하고 (b)그려라.','Let g(x)=x for x<1, g(1)=3, g(x)=2−x² for 1<x≤2, and g(x)=x−3 for x>2. (a)Find (i)lim₁₋g,(ii)lim₁g,(iii)g(1),(iv)lim₂₋g,(v)lim₂₊g,(vi)lim₂g. (b)Sketch the graph.'),[('1에서는 두 접근값이 1로 같지만 지정값은 3이다. 2에서는 왼쪽 2−4=−2, 오른쪽 2−3=−1이다.','At 1 both limiting values equal 1, while the assigned value is 3. At 2 the left value is 2−4=−2 and the right value is 2−3=−1.')],('(a)1,1,3,−2,−1,없음.','(a)1,1,3,−2,−1,does not exist.'),('1의 단일점 변경은 극한을 바꾸지 않으며, 2의 닫힌 점 −2는 좌우 불일치를 해소하지 않는다.','The single-point reassignment at 1 does not affect its limit; the filled value −2 at 2 does not resolve the disagreement of its one-sided limits.'),['a(i)','a(ii)','a(iii)','a(iv)','a(v)','a(vi)','b'])
D.fig(54,[panel('Hole at one and jump at two',(-1,4,-3,4),[[(-1,-1),(1,1)],samples(lambda z:2-z*z,1,2),[(2,-1),(4,1)]],[(1,1,'open'),(1,3),(2,-2),(2,-1,'open')],xticks=[-1,0,1,2,3,4])])
add(55,('바닥함수 ⌊x⌋에 대해 (a)−2⁺,−2,−2.4의 극한, (b)정수 n의 좌우 극한, (c)양쪽 극한이 존재하는 모든 a를 구하라.','For the floor function ⌊x⌋, find (a)the limits at −2⁺,−2,−2.4, (b)the one-sided limits at an integer n, and (c)all a with a two-sided limit.'),[('정수 n의 바로 왼쪽에서는 n−1, 바로 오른쪽에서는 n이다. 정수가 아닌 a는 한 계단의 내부에 있다.','Immediately left of an integer n the value is n−1; immediately right it is n. A noninteger a lies inside one constant step.')],('(a)−2,없음,−3. (b)왼쪽 n−1,오른쪽 n. (c)a∉ℤ.','(a)−2,does not exist,−3. (b)Left n−1,right n. (c)a∉ℤ.'),('−2.4는 (−3,−2)에 있어 바닥값 −3이다. 음수에서 0 쪽으로 버림한 −2와 혼동하지 않는다.','The number −2.4 lies in (−3,−2), so its floor is −3, not the truncation-toward-zero value −2.'),['a(i)','a(ii)','a(iii)','b(i)','b(ii)','c'])
add(56,('−π≤x≤π에서 f(x)=⌊cos x⌋이다. (a)그래프를 그리고 (b)0, (π/2)⁻, (π/2)⁺, π/2의 극한을 구하라. (c)극한이 존재하는 a를 기술하라.','For −π≤x≤π, let f(x)=⌊cos x⌋. (a)Sketch the graph. (b)Find limits at 0,(π/2)⁻,(π/2)⁺,π/2. (c)Describe the points a where a limit exists.'),[('|x|>π/2이면 −1, 0<|x|≤π/2이면 0, x=0이면 1이다.','The value is −1 for |x|>π/2, 0 for 0<|x|≤π/2, and 1 at x=0.'),('0에서는 양쪽의 값이 0이다. ±π/2에서는 계단이 바뀐다.','At zero both sides have value zero. The steps change at ±π/2.')],('(b)0,0,−1,없음. (c)내부 −π<a<π에서는 a≠±π/2. 끝점 ±π의 정의역 내 한쪽 극한도 −1이다.','(b)0,0,−1,does not exist. (c)For interior points −π<a<π, all a except ±π/2. The domain-relative one-sided limits at ±π also equal −1.'),('cos 0=1이어서 f(0)=1이지만 주변의 cos는 1보다 작아 바닥값이 0이다. 끝점은 양쪽 접근이 아닌 한쪽 접근임을 구분했다.','Although cos 0=1 gives f(0)=1, nearby cosine values are below 1 and have floor zero. Endpoint limits are explicitly distinguished as one-sided.'),['a','b(i)','b(ii)','b(iii)','b(iv)','c'])
D.fig(56,[panel('Floor of cosine',(-math.pi,math.pi,-1.5,1.5),[[(-math.pi,-1),(-math.pi/2,-1)],[(-math.pi/2,0),(0,0)],[(0,0),(math.pi/2,0)],[(math.pi/2,-1),(math.pi,-1)]],[(-math.pi,-1),(-math.pi/2,-1,'open'),(-math.pi/2,0),(0,0,'open'),(0,1),(math.pi/2,0),(math.pi/2,-1,'open'),(math.pi,-1)],xticks=[-math.pi,-math.pi/2,0,math.pi/2,math.pi],yticks=[-1,0,1])])
add(57,('f(x)=⌊x⌋+⌊−x⌋에서 x→2의 극한은 존재하지만 f(2)와 다름을 보여라.','Show that f(x)=⌊x⌋+⌊−x⌋ has a limit as x→2 that differs from f(2).'),[('정수가 아닌 x에 대해 n<x<n+1이면 −n−1<−x<−n이므로 두 바닥값의 합은 n+(−n−1)=−1이다.','If n<x<n+1 for a noninteger x, then −n−1<−x<−n, so the floor values sum to n+(−n−1)=−1.'),('0<|x−2|<1인 모든 x는 정수가 아니므로 f(x)=−1이다. 그러나 f(2)=2−2=0이다.','Every x with 0<|x−2|<1 is noninteger and has f(x)=−1. However, f(2)=2−2=0.')],d(r'\lim_{x\to2}f(x)=-1\ne0=f(2)'),('양쪽 모두 동일한 뚫린 근방에서 상수 −1임을 확인하므로 수치 추정에 의존하지 않는다.','The function is identically −1 on a full punctured neighborhood, proving both sides without numerical estimation.'))
add(58,('로런츠 길이 모형 L=L₀√(1−v²/c²)에서 v→c⁻의 극한을 해석하고 왼쪽 접근이 필요한 이유를 설명하라.','For the Lorentz length model L=L₀√(1−v²/c²), find and interpret the limit as v→c⁻ and explain why the approach is from the left.'),[('v→c⁻일 때 1−v²/c²→0⁺이므로 제곱근과 고정 상수 L₀의 곱은 0으로 간다.','As v→c⁻, 1−v²/c²→0⁺, so the root times the fixed constant L₀ tends to zero.'),('이 모형에서 관찰 길이는 속도가 c에 접근할수록 0에 가까워진다. 실수 근호와 주어진 물리 범위는 v<c 쪽이다.','In this model the observed length approaches zero as the speed approaches c. The real-valued formula and stated physical range require approach with v<c.')],d(r'\lim_{v\to c^-}L=0'),('v>c이면 근호 내부가 음수가 되어 이 실수값 모형의 오른쪽 접근을 사용할 수 없다.','For v>c the radicand is negative, excluding a right-hand approach within this real-valued model.'))
add(59,('임의의 다항식 p와 실수 a에 대해 lim(x→a)p(x)=p(a)를 극한 법칙으로 증명하라.','Prove from the limit laws that lim(x→a)p(x)=p(a) for any polynomial p and real a.'),[(d(r'p(x)=\sum_{k=0}^{n}c_kx^k'),d(r'p(x)=\sum_{k=0}^{n}c_kx^k')),('lim x=a에서 거듭제곱 법칙으로 lim xᵏ=aᵏ이다. 상수배 법칙과 유한 합 법칙을 차례로 적용한다.','Starting from lim x=a, the power law gives lim xᵏ=aᵏ. Apply constant multiplication and the finite-sum law term by term.')],d(r'\lim_{x\to a}p(x)=\sum_{k=0}^{n}c_ka^k=p(a)'),('k=0인 상수항은 상수 극한 법칙으로 처리하며 무한급수에 관한 가정은 필요하지 않다.','The k=0 term uses the constant-limit law, and no assertion about infinite series is needed.'))
add(60,('유리함수 r의 정의역에 있는 a에서 lim(x→a)r(x)=r(a)임을 다항식 극한을 이용해 증명하라.','Use polynomial limits to prove lim(x→a)r(x)=r(a) whenever a belongs to the domain of the rational function r.'),[('r=p/q로 쓰면 정의역 조건은 q(a)≠0이다. 각 다항식의 극한은 p(a),q(a)이다.','Write r=p/q. Its domain condition gives q(a)≠0, and the polynomial limits are p(a) and q(a).'),('분모 극한이 0이 아니므로 몫 법칙을 적용한다.','Since the denominator limit is nonzero, the quotient law applies.')],d(r'\lim_{x\to a}\frac{p(x)}{q(x)}=\frac{p(a)}{q(a)}=r(a)'),('q(a)=0인 구멍이나 점근선은 명제의 정의역 가정에서 제외되어 있다.','Zeros of q, including holes or possible asymptotes, are excluded by the domain hypothesis.'))
add(61,('lim(x→1)(f(x)−8)/(x−1)=10일 때 lim(x→1)f(x)를 구하라.','Given lim(x→1)(f(x)−8)/(x−1)=10, determine lim(x→1)f(x).'),[(d(r'f(x)=8+(x-1)\frac{f(x)-8}{x-1}\quad(x\ne1)'),d(r'f(x)=8+(x-1)\frac{f(x)-8}{x-1}\quad(x\ne1)')),('곱의 두 극한은 0과 10이므로 결과는 8+0·10이다.','The two factors have limits 0 and 10, giving 8+0·10.')],d('8'),('이 등식은 뚫린 근방에서 성립하므로 f(1)의 실제 값에 대한 가정은 없다.','The identity holds on a punctured neighborhood and makes no assumption about the assigned value f(1).'))
add(62,('lim(x→0)f(x)/x²=5이다. (a)lim f(x), (b)lim f(x)/x를 구하라.','Assume lim(x→0)f(x)/x²=5. Find (a)lim f(x) and (b)lim f(x)/x.'),[(d(r'f(x)=x^2\frac{f(x)}{x^2},\quad\frac{f(x)}x=x\frac{f(x)}{x^2}\quad(x\ne0)'),d(r'f(x)=x^2\frac{f(x)}{x^2},\quad\frac{f(x)}x=x\frac{f(x)}{x^2}\quad(x\ne0)')),('각각 0·5와 0·5로 극한을 계산한다.','The product limits are 0·5 in both cases.')],d(r'\text{(a) }0,\quad\text{(b) }0'),('주어진 비가 유한값 5로 가므로 근방에서 유계이며 x 또는 x²을 곱하면 0이 된다.','The given quotient approaches finite 5 and is therefore bounded nearby; multiplication by x or x² forces the product to zero.'),list('ab'))
add(63,('유리수 x에서는 f(x)=x², 무리수 x에서는 f(x)=0이다. x→0에서 f의 극한을 증명하라.','Define f(x)=x² at rational inputs and f(x)=0 at irrational inputs. Prove its limit as x→0.'),[('유리수인지 여부와 관계없이 0≤f(x)≤x²이다.','Regardless of rationality, 0≤f(x)≤x².'),('양쪽 경계가 0으로 가므로 조임정리로 극한은 0이다.','Both bounds approach zero, so the Squeeze Theorem gives a zero limit.')],d(r'\lim_{x\to0}f(x)=0'),('임의의 ε>0에 δ=√ε를 고르면 |x|<δ에서 |f(x)|≤x²<ε로 직접 확인할 수도 있다.','For any ε>0, choosing δ=√ε gives |f(x)|≤x²<ε whenever |x|<δ, providing a direct check.'))
for n,product in [(64,False),(65,True)]:
 op='곱'if product else'합';enop='product'if product else'sum'
 formula=r'f(x)=\operatorname{sgn}(x-a),\quad g(x)='+(''if product else'-')+r'\operatorname{sgn}(x-a)'
 add(n,(f'f와 g 각각의 x→a 극한은 없지만 {op}의 극한은 존재하는 예를 구성하라.',f'Construct f and g whose individual limits at a fail but whose {enop} has a limit.'),[(d(formula),d(formula)),('각 함수는 a의 좌우에서 서로 다른 ±1에 접근한다.','Each function approaches different values ±1 on the two sides of a.'),('x≠a에서 '+('fg=1'if product else'f+g=0')+'이므로 그 식의 극한은 존재한다.','For x≠a, '+('fg=1'if product else'f+g=0')+', so that expression has a limit.')],d(r'\lim_{x\to a}'+('f(x)g(x)=1'if product else'[f(x)+g(x)]=0')),('각 개별 함수의 두 한쪽 극한과 합성된 식의 상수값을 따로 확인했다.','Checked the two one-sided limits of each individual function and the constant value of the combined expression separately.'))
add(66,('극한 '+d(r'\lim_{x\to2}\frac{\sqrt{6-x}-2}{\sqrt{3-x}-1}')+'을 구하라.','Evaluate '+d(r'\lim_{x\to2}\frac{\sqrt{6-x}-2}{\sqrt{3-x}-1}')),[(d(r'\sqrt{6-x}-2=\frac{2-x}{\sqrt{6-x}+2},\quad\sqrt{3-x}-1=\frac{2-x}{\sqrt{3-x}+1}'),d(r'\sqrt{6-x}-2=\frac{2-x}{\sqrt{6-x}+2},\quad\sqrt{3-x}-1=\frac{2-x}{\sqrt{3-x}+1}')),(d(r'\frac{\sqrt{6-x}-2}{\sqrt{3-x}-1}=\frac{\sqrt{3-x}+1}{\sqrt{6-x}+2}\longrightarrow\frac24'),d(r'\frac{\sqrt{6-x}-2}{\sqrt{3-x}-1}=\frac{\sqrt{3-x}+1}{\sqrt{6-x}+2}\longrightarrow\frac24'))],d('1/2'),('x≠2에서만 공통인자 2−x를 약분했으며, 변형식 분모는 접근점에서 4로 0이 아니다.','Cancelled the common factor 2−x only for x≠2; the transformed denominator approaches nonzero 4.'))
add(67,('lim(x→−2)(3x²+ax+a+3)/(x²+x−2)가 유한하게 존재하도록 하는 a가 있는지 판단하고 극한값도 구하라.','Determine whether a can make lim(x→−2)(3x²+ax+a+3)/(x²+x−2) finite, and find the resulting limit.'),[('분모=(x+2)(x−1)이므로 분자도 −2에서 0이어야 한다. 대입하면 15−a=0이다.','The denominator is (x+2)(x−1), so the numerator must also vanish at −2. Substitution gives 15−a=0.'),(d(r'a=15:\quad\frac{3x^2+15x+18}{x^2+x-2}=\frac{3(x+2)(x+3)}{(x+2)(x-1)}=\frac{3(x+3)}{x-1}'),d(r'a=15:\quad\frac{3x^2+15x+18}{x^2+x-2}=\frac{3(x+2)(x+3)}{(x+2)(x-1)}=\frac{3(x+3)}{x-1}'))],d(r'a=15,\quad L=-1'),('a≠15이면 분자 극한이 0이 아니고 분모 부호가 바뀌어 유한 양쪽 극한이 불가능하므로 이 값은 유일하다.','If a≠15, the numerator has a nonzero limit and the denominator changes sign, excluding a finite two-sided limit; the choice is unique.'))
add(68,('고정 원 C₁:(x−1)²+y²=1과 원점 중심 반지름 r인 원 C₂가 있다. P=(0,r), Q는 위쪽 교점, R은 직선 PQ의 x절편이다. r→0⁺일 때 R의 위치를 구하라.','A fixed circle C₁ has equation (x−1)²+y²=1. Circle C₂ is centered at the origin with radius r. Let P=(0,r), let Q be their upper intersection, and let R be the x-intercept of line PQ. Find the limiting position of R as r→0⁺.'),[('두 원 식을 빼면 2x=r²이다. 0<r<2에서 위쪽 교점은 다음과 같다.','Subtracting the circle equations gives 2x=r². For 0<r<2, the upper intersection is'),(d(r'Q=\left(\frac{r^2}{2},r\sqrt{1-r^2/4}\right)'),d(r'Q=\left(\frac{r^2}{2},r\sqrt{1-r^2/4}\right)')),(d(r'R_x=\frac{r(r^2/2)}{r-r\sqrt{1-r^2/4}}=\frac{r^2}{2(1-\sqrt{1-r^2/4})}=2\left(1+\sqrt{1-r^2/4}\right)'),d(r'R_x=\frac{r(r^2/2)}{r-r\sqrt{1-r^2/4}}=\frac{r^2}{2(1-\sqrt{1-r^2/4})}=2\left(1+\sqrt{1-r^2/4}\right)'))],d(r'R\longrightarrow(4,0)'),('구한 Q를 두 원에 대입하고 P,Q,R의 기울기가 같은지 확인했다. r=.5와 .1에서 Rₓ≈3.93649,3.99750으로 4에 접근한다.','Substituted Q into both circles and checked collinearity of P,Q,R. At r=.5 and .1, Rₓ≈3.93649 and 3.99750, approaching 4.'))
pps=[]
for rad in [1,.4]:
 qx=rad*rad/2;qy=rad*math.sqrt(1-rad*rad/4);rx=2*(1+math.sqrt(1-rad*rad/4))
 circles=[[(1+math.cos(t),math.sin(t))for t in [2*math.pi*k/200 for k in range(201)]],[(rad*math.cos(t),rad*math.sin(t))for t in [2*math.pi*k/200 for k in range(201)]],[(0,rad),(rx,0)]]
 pps.append(panel(f'Circles and line PQ: r={rad:g}; R x={rx:.4f}',(-1.2,4.3,-1.2,1.4),circles,[(0,rad),(qx,qy),(rx,0)],xticks=[-1,0,1,2,3,4]))
D.fig(68,pps,('서로 다른 두 반지름에서 직접 계산한 원·교점·직선.','Circles, intersections, and secant lines computed for two radii.'))
